// Browser data API for the review archive.
//
// The full archive (~2,500 reviews) no longer lives in the main bundle. A
// compact manifest (manifest.json, generated by scripts/gen/gen-reviews.mjs)
// carries everything cards, search, hero stats and offer pages need, and the
// full article bodies live in lazy-loaded chunks (generated/chunk-NNN.json).
// Both are only ever imported dynamically, so the main chunk stays small.
//
// buildArchive() expands the compact manifest entries back into the same
// review shape the components always used (long field names, scorecard object,
// derived ctaUrl), so pages work against it like they worked against
// REVIEWS/PAGINATED before.

export const PAGE_SIZE = 9

export const DIM_KEYS = ['easeOfUse', 'features', 'transparency', 'security', 'support']

export function dimsToObject(dims) {
  return {
    easeOfUse: dims[0],
    features: dims[1],
    transparency: dims[2],
    security: dims[3],
    support: dims[4],
  }
}

// Same derivation as src/data/reviews/index.js - every review's CTA buttons
// point at the Austerio campaign landing unless the review overrides it.
export function ctaUrlFor(name) {
  return `https://austerio-smart-up.com/?f=${encodeURIComponent(name)}&subid=BIT`
}

let manifestPromise = null
export function loadManifest() {
  // Module-level cache: StrictMode double-effects and re-navigations share
  // one fetch, and Vite's import() cache covers the rest.
  manifestPromise ??= import('./manifest.json').then((m) => buildArchive(m.default?.articles ?? m.articles ?? []))
  return manifestPromise
}

const chunkCache = new Map()
export function loadChunk(chunkId) {
  if (!chunkCache.has(chunkId)) {
    chunkCache.set(
      chunkId,
      import(`./generated/chunk-${String(chunkId).padStart(3, '0')}.json`).then((m) => m.default ?? m),
    )
  }
  return chunkCache.get(chunkId)
}

export function buildArchive(entries) {
  const articles = entries.map((e) => ({
    slug: e.s,
    keyword: e.k,
    name: e.n,
    headline: e.h,
    byline: e.b,
    date: e.d,
    isoDate: e.i,
    readTime: e.t,
    rating: e.r,
    verdict: e.v,
    accent: e.a,
    path: e.p,
    excerpt: e.e,
    deck: e.x,
    minimumDeposit: e.m,
    scorecard: dimsToObject(e.c),
    chunkId: e.g,
    ctaUrl: e.u || ctaUrlFor(e.n),
  }))
  const byRating = [...articles].sort((a, b) => b.rating - a.rating)
  return {
    articles,
    byRating,
    featured: byRating[0],
    bySlug: new Map(articles.map((r) => [r.slug, r])),
    byPath: new Map(articles.map((r) => [r.path, r])),
    byKeyword: new Map(articles.map((r) => [r.keyword, r])),
    count: articles.length,
    cautionCount: articles.filter((r) => r.verdict.startsWith('CAUTION')).length,
    latestDate: articles.reduce((a, b) => (b.isoDate > a.isoDate ? b : a), articles[0]).date,
  }
}
